import { errorResult, okResult, type CliCommandResult } from '../envelope';
import { isCommandResult, parseCommandContext } from './shared';
import { errorMessage } from '../../utils/errorMessage';

const COMMAND = 'auth.status';

export const handleAuthStatus = async (
  args: string[],
): Promise<CliCommandResult> => {
  const context = parseCommandContext(COMMAND, args);
  if (isCommandResult(context)) {
    return context;
  }

  const { getConfigManager } = await import('../../services/ConfigManager');
  const configManager = getConfigManager();
  if (!configManager.isAuthenticated()) {
    return okResult(COMMAND, { authenticated: false });
  }

  const { AuthService } = await import('../../services/AuthService');
  try {
    const profile = await new AuthService().getValidatedProfile();
    if (!profile) {
      return okResult(COMMAND, { authenticated: false });
    }
    return okResult(COMMAND, {
      authenticated: true,
      email: configManager.getEmail(),
      userId: configManager.getUserId(),
    });
  } catch (error) {
    return errorResult(
      COMMAND,
      'OPERATION_FAILED',
      errorMessage(error, 'Auth status check failed'),
    );
  }
};

export const handleAuth = async (args: string[]): Promise<CliCommandResult> => {
  const action = args[0];
  if (action === 'status') {
    return handleAuthStatus(args.slice(1));
  }
  return errorResult(
    'auth',
    'USAGE_ERROR',
    'Usage: rivet auth status (use `rivet login` / `rivet logout` to change auth state)',
  );
};
